import fitz, re, os, pathlib

EMAIL_RE = re.compile(r'[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}')
ARXIV_RE = re.compile(r'arxiv\s*:\s*\d{4}\.\d{4,5}(v\d+)?', re.I)

AUTHOR_KEYWORDS = [
    'correspondence', 'equal contribution', 'corresponding author'
]
AFFIL_KEYWORDS = [
    'university', 'institute', 'laboratory', 'college', 'school', 'department',
    'inc', 'corp', 'llc', 'ltd', 'gmbh', 'co.', 'company'
]
FUNDING_KEYWORDS = [
    'supported', 'funded', 'grant', 'nsf', 'aro', 'darpa', 'onr', 'doe', 'nih',
    'afosr', 'epsrc', 'erc', 'ukri', 'horizon'
]
VENUE_KEYWORDS = [
    'interspeech', 'icml', 'neurips', 'iclr', 'acl', 'emnlp', 'naacl', 'aaai',
    'cvpr', 'eccv', 'iccv', 'icassp', 'kdd', 'siggraph', 'sigcomm', 'sigir',
    'sigkdd', 'ijcai', 'colt', 'icra', 'iros', 'www', 'the web conference'
]
VENUE_GENERIC = ['workshop', 'conference', 'proceedings', 'symposium']


def block_text(block_dict):
    texts = []
    for line in block_dict.get('lines', []):
        for span in line.get('spans', []):
            t = span.get('text', '')
            if t:
                texts.append(t)
        texts.append('\n')
    return ''.join(texts).strip()


def find_title_bbox(page):
    data = page.get_text('dict')
    max_size = -1
    title_bbox = None
    title_text = ''
    for b in data.get('blocks', []):
        if b.get('type', 1) != 0:
            continue
        text = block_text(b)
        if not text:
            continue
        if re.search(r'\babstract\b', text, re.I):
            continue
        max_span = max((s.get('size', 0) for line in b.get('lines', []) for s in line.get('spans', [])), default=0)
        if max_span > max_size:
            max_size = max_span
            title_bbox = b.get('bbox')
            title_text = text
    return title_bbox, title_text


def rects_for_line(page, line):
    # Try exact line, then dehyphenated
    rects = page.search_for(line)
    if not rects:
        rects = page.search_for(line, flags=fitz.TEXT_DEHYPHENATE)
    return rects


def redact_pdf(src, dst):
    doc = fitz.open(src)
    for page_index, page in enumerate(doc):
        height = page.rect.height
        header_thresh = 0.15 * height
        footer_thresh = 0.15 * height

        blocks = page.get_text('blocks')
        text = page.get_text()
        text_lower = text.lower()

        # First page: redact everything above Abstract except title
        if page_index == 0:
            abstract_y0 = None
            for b in blocks:
                if re.search(r'\babstract\b', b[4], re.I):
                    abstract_y0 = b[1]
                    break
            title_bbox, _ = find_title_bbox(page)

            if abstract_y0 is not None and title_bbox is not None:
                tx0, ty0, tx1, ty1 = title_bbox
                for b in blocks:
                    x0, y0, x1, y1, btext = b[:5]
                    if not btext.strip():
                        continue
                    if y1 < abstract_y0:
                        # Keep title block only
                        intersects_title = not (x1 < tx0 or x0 > tx1 or y1 < ty0 or y0 > ty1)
                        if not intersects_title:
                            page.add_redact_annot(fitz.Rect(x0, y0, x1, y1), fill=(0, 0, 0))

        # Block-based redactions for author/affiliation/funding/venue cues
        for b in blocks:
            x0, y0, x1, y1, btext = b[:5]
            if not btext.strip():
                continue
            tnorm = ' '.join(btext.split())
            tlow = tnorm.lower()

            if any(k in tlow for k in AUTHOR_KEYWORDS):
                page.add_redact_annot(fitz.Rect(x0, y0, x1, y1), fill=(0, 0, 0))
                continue

            if page_index == 0 and any(k in tlow for k in AFFIL_KEYWORDS):
                page.add_redact_annot(fitz.Rect(x0, y0, x1, y1), fill=(0, 0, 0))
                continue

            if 'acknowledg' in tlow or any(k in tlow for k in FUNDING_KEYWORDS):
                page.add_redact_annot(fitz.Rect(x0, y0, x1, y1), fill=(0, 0, 0))
                continue

            if any(k in tlow for k in VENUE_KEYWORDS) or any(k in tlow for k in VENUE_GENERIC):
                if y0 < header_thresh or y1 > height - footer_thresh or page_index == 0:
                    page.add_redact_annot(fitz.Rect(x0, y0, x1, y1), fill=(0, 0, 0))
                    continue

            if 'copyright' in tlow or '©' in tnorm:
                page.add_redact_annot(fitz.Rect(x0, y0, x1, y1), fill=(0, 0, 0))
                continue

        # Redact emails precisely
        for email in sorted(set(EMAIL_RE.findall(text))):
            for r in page.search_for(email):
                page.add_redact_annot(r, fill=(0, 0, 0))

        # Redact arXiv lines precisely
        if 'arxiv' in text_lower:
            for line in text.splitlines():
                if re.search(r'arxiv', line, re.I):
                    line_clean = ' '.join(line.split())
                    for r in rects_for_line(page, line_clean):
                        page.add_redact_annot(r, fill=(0, 0, 0))

        # Apply
        page.apply_redactions()

    # Remove metadata
    doc.set_metadata({})
    pathlib.Path(os.path.dirname(dst)).mkdir(parents=True, exist_ok=True)
    doc.save(dst)
    doc.close()

for i in range(1,4):
    src = f'/root/paper{i}.pdf'
    dst = f'/root/redacted/paper{i}.pdf'
    redact_pdf(src, dst)
    print('redacted', src, '->', dst)
