import fitz, re

def find_matches(path, pattern, max_hits=5):
    doc=fitz.open(path)
    print('\n',path,'pattern',pattern)
    hits=0
    for i,page in enumerate(doc):
        text=page.get_text()
        for line in text.splitlines():
            if re.search(pattern, line, re.I):
                print(f' page {i+1}: {line[:200]}')
                hits+=1
                if hits>=max_hits:
                    doc.close(); return
    doc.close()

for pat in ['university','icml','interspeech']:
    for i in range(1,4):
        find_matches(f'/root/redacted/paper{i}.pdf', pat)
